const ev = $input.first().json.headers['x-github-event'];
const b = $input.first().json.body || {};
let text = null;
const line = (s) => (s || '').split('\n')[0];
if (ev === 'push') {
  const br = (b.ref || '').replace('refs/heads/', '');
  if (br.startsWith('claude/') || br === 'main') {
    const files = new Set();
    (b.commits || []).forEach(c => [...(c.added || []), ...(c.modified || []), ...(c.removed || [])].forEach(f => files.add(f)));
    text = `📦 Push lên ${br} (${(b.commits || []).length} commit, ${files.size} file đổi)\n${line((b.head_commit || {}).message)}\n${b.compare || ''}`;
  }
} else if (ev === 'pull_request') {
  const pr = b.pull_request || {};
  if (b.action === 'opened') text = `🔀 PR mới #${pr.number}: ${pr.title}\n${pr.html_url}`;
  else if (b.action === 'closed') text = `${pr.merged ? '✅ PR đã gộp' : '🚫 PR đã đóng'} #${pr.number}: ${pr.title}\n${pr.html_url}`;
} else if (ev === 'workflow_run') {
  const r = b.workflow_run || {};
  if (b.action === 'completed' && r.conclusion === 'failure') text = `🔴 Test ĐỎ trên ${r.head_branch}\n${line((r.head_commit || {}).message)}\n${r.html_url}`;
}
return [{ json: { text, skip: !text } }];
